INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH020270', 'AN1887', '塩崎茨', 'Quirk: Vine  Student in Class 1-B at U.A. High School.  Ibara is a very modest and courteous person. Although graceful and soft-spoken, she is not afraid to make her pure intentions known. She seems highly religious due to her talking about heaven and divine beings in passing on multiple occasions, and her ultimate moves having somewhat religious names such as "Faith''s Shield" and "Crucifixion".  Ibara''s Quirk "Vine (ツル, Tsuru) gives her hair-like vines that grow on her head. She can lengthen an', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b127426-Amaf70JKHWyn.png', '9月8日', 'AB', '真坂美帆', 167, 127426, 'SUPPORTING', 132) ON CONFLICT DO NOTHING;
