INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH020354', 'AN1890', '鳳橋楼十郎', 'Rojuro Otoribashi, commonly referred to as Rose (ローズ, Rōzu?), is the former captain of the 3rd Division. He became captain approximately one year before Kisuke Urahara. He is an effeminate man with long, wavy, blond hair and a frilly shirt. He seems to be interested in music, as he speaks to Love about an artist&#039;s new single and has been seen playing or tuning a guitar on several occasions. Rose appears to be one of the calmer and perhaps wiser ones amongst the group, though he becomes irri', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b2341-9TX1HBmLggia.png', '3月17日', NULL, '樫井笙人', NULL, 2341, 'SUPPORTING', 43) ON CONFLICT DO NOTHING;
