INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH020360', 'AN1890', 'キルゲ・オピー', 'Race: Quincy     Affiliation: Vandenreich   Occupation: Executive Hunting Captain of the first Jagdarmee   Team: First Jagdarmee   Base of Operations: Hueco Mundo    Quilge Opie is the executive hunting captain (統括狩猟隊長, tōkatsu shuryō taichō) of the first Jagdarmee of the Vandenreich.   (Source: Bleach Wikia)', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b60535-L30Mu5HzErKv.png', '9月1日', NULL, '山寺宏一', NULL, 60535, 'SUPPORTING', 23) ON CONFLICT DO NOTHING;
