INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH020366', 'AN1890', 'ジェローム・ギズバット', 'Jerome Guizbatt (ジェローム・ギズバット, Jerōmu Gizubatto) is a Quincy and member of the Vandenreich''s Stern Ritter with the designation "R".  Jerome is one of three Stern Ritter to confront Captain Kenpachi Zaraki during the invasion''s initial stages. However, according to Zaraki''s account, despite attempting to use his ability, Jerome is easily and fatally cut right down the middle. Zaraki later impales and then carries Jerome''s corpse atop his shoulders, along with two other Stern Ritter, before uncerem', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/72099.jpg', NULL, NULL, '貴弘藤原', NULL, 72099, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
