INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH020370', 'AN1890', 'シアン・スンスン', 'Arrancar 56 Cyan Sung-Sun (シィアン・スンスン, Shyian Sunsun?) is one of Tier Halibel''s Fracción. In her early life, she was a snake-like Adjuchas who was a part of Halibel''s team alongside Franceska Mila Rose. She was present when Emilou Apacci was introduced to them. Sometime after Halibel''s audience with Baraggan, she and the others tried to help Halibel when her base was attacked by a Hammerhead Arrancar only for them to be saved by Aizen.    Her Zanpakutō is Anaconda (白蛇姫 (アナコンダ), Anakonda?, Spanish', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/17150.jpg', NULL, NULL, '瀬那歩美', NULL, 17150, 'SUPPORTING', 66) ON CONFLICT DO NOTHING;
