INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH020377', 'AN1890', 'ドンドチャッカ・ビルスタン', 'Dondochakka Birstanne (ドンドチャッカ・ビルスタン, Dondochakka Birusutan) is one of Nel Tu''s "brothers" and protectors. Like Pesche, he attempts to chase after Nel and Ichigo in Las Noches, but ends up finding Renji instead, who he frequently irritates with his clumsiness and emotional outbursts.  Dondochakka has a large, spotted humanoid hollow with a tiki mask and compound eyes. He appears to speak with a yakuza-style accent and is fairly tame in comparison to other hollows. Despite his menacing appearance', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/8021.jpg', NULL, NULL, '郷里大輔', NULL, 8021, 'SUPPORTING', 52) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH020378', 'AN1890', '壷府リン', 'Rin Tsubokura (壷府 リン, Tsubokura Rin) is a Shinigami who bears a strong resemblance to the 7th Seat of the 4th Division Hanatarō Yamada, he is almost always showing a face of distress or preocupation, he has (oddly) a small pigtail done in his front side of his hair. He is a researcher of the Shinigami Research and Development Institute and has a fondness for candy and sweets. He is a bit clumsy, as shown in a shinigami golden cup where he fell on the sweets, but they where unbreakable. During on', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/15457.jpg', '2月24日', NULL, '斉木美帆', NULL, 15457, 'SUPPORTING', 11) ON CONFLICT DO NOTHING;
